import{_ as t,o as a,c as o,ah as n}from"./chunks/framework.DDXs_i7t.js";const d=JSON.parse('{"title":"Indictment against Wolf and Schelling: The Highway Deal","description":"The WKStA files charges for an illegal tax reduction of 630,000 euros. A lesson in the pointillism of money.","frontmatter":{"title":"Indictment against Wolf and Schelling: The Highway Deal","description":"The WKStA files charges for an illegal tax reduction of 630,000 euros. A lesson in the pointillism of money.","date":"2026-03-26T00:00:00.000Z"},"headers":[],"relativePath":"en/logbuch/2026-03-26-wolf-schelling-anklage.md","filePath":"en/logbuch/2026-03-26-wolf-schelling-anklage.md"}'),i={name:"en/logbuch/2026-03-26-wolf-schelling-anklage.md"};function r(l,e,s,h,c,f){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="indictment-against-wolf-and-schelling-the-highway-deal" tabindex="-1">Indictment against Wolf and Schelling: The Highway Deal <a class="header-anchor" href="#indictment-against-wolf-and-schelling-the-highway-deal" aria-label="Permalink to &quot;Indictment against Wolf and Schelling: The Highway Deal&quot;">​</a></h1><p>On March 26, 2026, news reached us: The Economic and Corruption Prosecutor&#39;s Office (WKStA) is bringing Siegfried Wolf and Hans Jörg Schelling to court. It is another piece of the mosaic in our image of <strong>System Austria</strong>.</p><h3 id="the-facts-of-the-case" tabindex="-1">The Facts of the Case <a class="header-anchor" href="#the-facts-of-the-case" aria-label="Permalink to &quot;The Facts of the Case&quot;">​</a></h3><p>It involves allegations from 2018. Siegfried Wolf is alleged to have received an unlawful tax reduction in the amount of <strong>630,000 euros</strong>.</p><ul><li><strong>Place of Occurrence:</strong> A highway service station. Here, Wolf met with the head of the competent tax office.</li><li><strong>The Deal:</strong> Wolf promised support for her career (head of a larger tax office); in return, she was to check his tax matter &quot;benevolently.&quot;</li><li><strong>The Intervention:</strong> Ex-Finance Minister Schelling is alleged to have intervened with the then Secretary General Thomas Schmid after leaving office in order to increase the pressure on the financial administration.</li></ul><h3 id="context-for-the-docfilm-project" tabindex="-1">Context for the &quot;Docfilm&quot; Project <a class="header-anchor" href="#context-for-the-docfilm-project" aria-label="Permalink to &quot;Context for the &quot;Docfilm&quot; Project&quot;">​</a></h3><p>This case is the perfect example of what we call the <strong>&quot;pointillism of money&quot;</strong> in the film.</p><ol><li><strong>Informal Channels:</strong> Meetings away from offices, at service stations, or in back rooms.</li><li><strong>Patronage as Currency:</strong> You don&#39;t pay with suitcases full of money, but with promises of career and influence.</li><li><strong>The Thomas Schmid Network:</strong> Once again, it is clear that in the Ministry of Finance of the Kurz/Löger era, all threads converged with Schmid.</li></ol><p>The Federal Tax Court and the Supreme Administrative Court have already revoked the tax assessment as unlawful. Now follow the criminal proceedings.</p><p><em>Researched by Gemini CLI for the project &quot;HortenMystery&quot;. March 2026.</em></p>',10)])])}const m=t(i,[["render",r]]);export{d as __pageData,m as default};
